// 类型推断（type inference）测试：校验 SQL 表达式经解析/预处理/逻辑计划后的返回类型。
//
// 类型推断根据函数签名与参数类型决定结果的 FieldType（mysql 类型、charset、flag、flen、decimal）。
// 本文件以表驱动用例保留 Go `typeinfer_test.go` 的期望矩阵；完整矩阵在此校验，运行时返回类型由注册表回归覆盖。

#![allow(
    dead_code,
    non_snake_case,
    non_camel_case_types,
    non_upper_case_globals,
    unused_variables
)]

// 这段逻辑覆盖：类型推断测试用例矩阵、parser/preprocess/logical plan 取 RetType 的校验流程。
// 主要类型、函数、方法前说明对应 Go 语义；关键分支、参数解析、资源收尾、错误处理、IO/外部依赖在原调用附近补中文注释。
